<?php

namespace App\Support;

/**
 * The icon set: Phosphor glyphs under the app's own names.
 *
 * resources/icons/phosphor.php is generated by scripts/build-icons.mjs and
 * committed, so rendering needs no node_modules. Loaded once per request.
 *
 * @see resources/views/components/icon.blade.php
 */
class Icons
{
    /** @var array<string, array{string, string}>|null */
    private static ?array $set = null;

    /**
     * The inner markup of a 256x256 SVG. An unknown name returns the question
     * mark glyph, so a typo shows on screen instead of leaving a silent gap.
     */
    public static function markup(string $name, bool $fill = false): string
    {
        self::$set ??= require resource_path('icons/phosphor.php');

        $glyph = self::$set[$name] ?? self::$set['help'];

        return $glyph[$fill ? 1 : 0];
    }

    public static function has(string $name): bool
    {
        self::$set ??= require resource_path('icons/phosphor.php');

        return isset(self::$set[$name]);
    }
}
